export function getDashboardLocaleBundle(lang) {
  const code = normalizeSupportedLanguageCode(lang) || DEFAULT_LANGUAGE_CODE;
  return DASHBOARD_LOCALES[code] || {};
}

export function overlayDashboardLocaleForLanguage(lang) {
  const bundle = getDashboardLocaleBundle(lang);
  if (bundle && Object.keys(bundle).length) overlayI18nStrings(bundle);
}
